using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Newtonsoft.Json;
using UnityEngine;
using UnityEditor;
using UnityEditor.U2D.Sprites;
using ShorelineDefense.Presentation;
using ShorelineDefense.Enemies;
using ShorelineDefense.Waves;
public static class Phase4CArt {
 const string Art="Assets/Game/Art/", Raw=Art+"SourceSheets/p4c_content_001/";
 static readonly List<object> evidence=new List<object>();
 static void Set(UnityEngine.Object o,string key,UnityEngine.Object v){var s=new SerializedObject(o);s.FindProperty(key).objectReferenceValue=v;s.ApplyModifiedPropertiesWithoutUndo();EditorUtility.SetDirty(o);}
 static void Array(UnityEngine.Object o,string key,Sprite[] frames){var s=new SerializedObject(o);var p=s.FindProperty(key);p.arraySize=frames.Length;for(int i=0;i<frames.Length;i++)p.GetArrayElementAtIndex(i).objectReferenceValue=frames[i];s.ApplyModifiedPropertiesWithoutUndo();}
 static Texture2D Read(string p){var t=new Texture2D(2,2,TextureFormat.RGBA32,false);t.LoadImage(File.ReadAllBytes(p));evidence.Add(new{raw=p,width=t.width,height=t.height});return t;}
 static RectInt Bounds(Texture2D t,int col,int row,int cols,int rows){int x0=Mathf.RoundToInt(col*t.width/(float)cols),x1=Mathf.RoundToInt((col+1)*t.width/(float)cols);int y0=Mathf.RoundToInt((rows-row-1)*t.height/(float)rows),y1=Mathf.RoundToInt((rows-row)*t.height/(float)rows);int l=x1,r=x0,b=y1,u=y0;var pixels=t.GetPixels32();for(int y=y0;y<y1;y++)for(int x=x0;x<x1;x++){if(pixels[y*t.width+x].a<220)continue;l=Math.Min(l,x);r=Math.Max(r,x);b=Math.Min(b,y);u=Math.Max(u,y);}if(r<l||u<b)throw new Exception("Empty cell "+col+","+row);return new RectInt(l,b,r-l+1,u-b+1);}
 static Color32[] Fit(Texture2D t,RectInt b,int width,int height,float scale){var src=t.GetPixels32();var result=new Color32[width*height];float cx=b.x+b.width*.5f,cy=b.y+b.height*.5f;for(int y=0;y<height;y++)for(int x=0;x<width;x++){int sx=Mathf.FloorToInt(cx+(x+.5f-width*.5f)/scale),sy=Mathf.FloorToInt(cy+(y+.5f-height*.5f)/scale);if(sx<b.x||sx>=b.xMax||sy<b.y||sy>=b.yMax)continue;var p=src[sy*t.width+sx];if(p.a<220)continue;result[y*width+x]=new Color32((byte)(p.r/8*8),(byte)(p.g/8*8),(byte)(p.b/8*8),255);}return result;}
 static Sprite[] Save(string path,Color32[][] cells,int width,int height,float ppu=51.2f){Directory.CreateDirectory(Path.GetDirectoryName(path));var t=new Texture2D(width*cells.Length,height,TextureFormat.RGBA32,false);for(int i=0;i<cells.Length;i++)t.SetPixels32(i*width,0,width,height,cells[i]);t.Apply();File.WriteAllBytes(path,t.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);
  var imp=(TextureImporter)AssetImporter.GetAtPath(path);imp.textureType=TextureImporterType.Sprite;imp.spriteImportMode=cells.Length==1?SpriteImportMode.Single:SpriteImportMode.Multiple;imp.filterMode=FilterMode.Point;imp.textureCompression=TextureImporterCompression.Uncompressed;imp.mipmapEnabled=false;imp.wrapMode=TextureWrapMode.Clamp;imp.npotScale=TextureImporterNPOTScale.None;imp.maxTextureSize=4096;imp.spritePixelsPerUnit=ppu;var textureSettings=new TextureImporterSettings();imp.ReadTextureSettings(textureSettings);textureSettings.spriteMeshType=SpriteMeshType.FullRect;imp.SetTextureSettings(textureSettings);imp.alphaSource=TextureImporterAlphaSource.FromInput;imp.alphaIsTransparency=true;imp.isReadable=false;imp.SaveAndReimport();
  if(cells.Length>1){var factories=new SpriteDataProviderFactories();factories.Init();var provider=factories.GetSpriteEditorDataProviderFromObject(imp);provider.InitSpriteEditorDataProvider();var old=provider.GetSpriteRects();var rects=Enumerable.Range(0,cells.Length).Select(i=>new SpriteRect{name=Path.GetFileNameWithoutExtension(path)+"__f"+i.ToString("D3"),rect=new Rect(i*width,0,width,height),pivot=new Vector2(.5f,.5f),alignment=SpriteAlignment.Center,spriteID=i<old.Length?old[i].spriteID:GUID.Generate()}).ToArray();provider.SetSpriteRects(rects);provider.GetDataProvider<ISpriteNameFileIdDataProvider>().SetNameFileIdPairs(rects.Select(r=>new SpriteNameFileIdPair(r.name,r.spriteID)));provider.Apply();imp.SaveAndReimport();}
  evidence.Add(new{runtime=path,width=width*cells.Length,height,ppu,frames=cells.Length,alpha="binary 220 threshold",colors="five-bit channels no dither",fit="nearest neighbor centered bounds; one common scale per character"});return AssetDatabase.LoadAllAssetsAtPath(path).OfType<Sprite>().OrderBy(s=>s.name).ToArray();
 }
 static Sprite[] Character(string id,string raw,int size){var source=Read(Raw+raw);var bounds=Enumerable.Range(0,20).Select(i=>Bounds(source,i%4,i/4,4,5)).ToArray();float scale=Math.Min((size-12f)/bounds.Max(b=>b.width),(size-12f)/bounds.Max(b=>b.height));string[] actions={"idle","move","attack","hit","death"};var sequences=new List<Sprite[]>();for(int row=0;row<5;row++){string path=Art+"Enemies/Special/"+id+"_"+actions[row]+"_v002.png";var frames=Save(path,Enumerable.Range(row*4,4).Select(i=>Fit(source,bounds[i],size,size,scale)).ToArray(),size,size);sequences.Add(frames);
   string clipPath="Assets/Game/Animations/Enemies/Special/"+id+"_"+actions[row]+".anim";Directory.CreateDirectory(Path.GetDirectoryName(clipPath));var clip=AssetDatabase.LoadAssetAtPath<AnimationClip>(clipPath);if(clip==null){clip=new AnimationClip();AssetDatabase.CreateAsset(clip,clipPath);}clip.frameRate=row==1?(id=="PirateRunner"?12:8):row==4?9:10;var settings=AnimationUtility.GetAnimationClipSettings(clip);settings.loopTime=row<3;AnimationUtility.SetAnimationClipSettings(clip,settings);AnimationUtility.SetObjectReferenceCurve(clip,new EditorCurveBinding{path="Visual/Body",type=typeof(SpriteRenderer),propertyName="m_Sprite"},frames.Select((s,i)=>new ObjectReferenceKeyframe{time=i/clip.frameRate,value=s}).ToArray());EditorUtility.SetDirty(clip);
  }
  var root=PrefabUtility.LoadPrefabContents("Assets/Game/Prefabs/Enemies/"+id+"_TopDown.prefab");try{var body=root.transform.Find("Visual/Body").GetComponent<SpriteRenderer>();body.sprite=sequences[0][0];body.color=Color.white;body.transform.localScale=Vector3.one;var presentation=root.GetComponent<EnemySpritePresentation>();foreach(var pair in new[]{new{key="idle",index=0},new{key="walk",index=1},new{key="attack",index=2},new{key="hit",index=3},new{key="death",index=4}})Array(presentation,pair.key,sequences[pair.index]);PrefabUtility.SaveAsPrefabAsset(root,"Assets/Game/Prefabs/Enemies/"+id+"_TopDown.prefab");}finally{PrefabUtility.UnloadPrefabContents(root);}
  UnityEngine.Object.DestroyImmediate(source);return sequences[0];
 }
 static Sprite Single(string raw,string path,int width,int height){var source=Read(Raw+raw);var bounds=Bounds(source,0,0,1,1);float scale=Math.Min((width-8f)/bounds.width,(height-8f)/bounds.height);var frames=Save(path,new[]{Fit(source,bounds,width,height,scale)},width,height);UnityEngine.Object.DestroyImmediate(source);return frames[0];}
 public static string Apply(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");
  Character("IsisBreacher","breacher_v002.png",64);Character("IsisHeavy","heavy_v002.png",64);Character("PirateRunner","runner_v002.png",64);Character("PirateRaider","raider_v002.png",64);
  if(File.Exists(Raw+"pirateBoss_v003.png")){var frames=Character("PirateWarlord","pirateBoss_v003.png",96);Set(AssetDatabase.LoadAssetAtPath<BossDefinition>("Assets/Game/Data/Enemies/PirateWarlord.asset"),"bossArt",frames[0]);}
  foreach(var pair in new[]{new{raw="militantBoat_v001.png",name="MilitantBossTransport"},new{raw="pirateBoat_v001.png",name="PirateBossTransport"}}){var sprite=Single(pair.raw,Art+"Props/"+pair.name+"_v001.png",192,96);var path="Assets/Game/Prefabs/Presentation/"+pair.name+".prefab";var root=PrefabUtility.LoadPrefabContents(path);try{var hull=root.GetComponentsInChildren<SpriteRenderer>(true).First(r=>r.name=="Rubber Boat");hull.sprite=sprite;hull.transform.localScale=Vector3.one;hull.color=Color.white;PrefabUtility.SaveAsPrefabAsset(root,path);}finally{PrefabUtility.UnloadPrefabContents(root);}}
  Single("toolsIcon_v001.png",Art+"UI/ui_icon_dismantle.png",64,64);
  foreach(var file in Directory.GetFiles(Raw,"*.png")){var imp=AssetImporter.GetAtPath(file) as TextureImporter;if(imp==null)continue;imp.textureType=TextureImporterType.Default;imp.filterMode=FilterMode.Point;imp.textureCompression=TextureImporterCompression.Uncompressed;imp.mipmapEnabled=false;imp.maxTextureSize=4096;imp.SaveAndReimport();}
  AssetDatabase.SaveAssets();File.WriteAllText("Docs/Validation/Phase4C/art-import.json",JsonConvert.SerializeObject(evidence,Formatting.Indented));return "Five generated animation sets, boss transports, dismantle icon integrated; Osama art remains existing placeholder";
 }
}

